```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mocks for contexts
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartWithItems = {
  items: [{ id: '1', name: 'Excalibur', price: 999.99 }],
  total: 999.99,
  clearCart: mockClearCart,
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCartWithItems,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-CAMELOT-001' });
  });

  // 1. HAPPY PATH - Complete checkout flow
  describe('Happy Path - Complete Checkout', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      render(<Checkout onComplete={mockOnComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '1 Round Table Way');
      await user.type(screen.getByLabelText(/city/i), 'Camelot');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'King Arthur');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/excalibur/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-CAMELOT-001')).toBeInTheDocument();
      expect(mockOnComplete).toHaveBeenCalledWith('ORD-CAMELOT-001');
    });
  });

  // 2. FORM VALIDATION
  describe('Form Validation', () => {
    it('displays shipping validation errors for empty fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByText(/city is required/i)).toBeInTheDocument();
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // 3. ERROR STATES
  describe('Payment Error Handling', () => {
    it('displays payment failure and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);
      // ...navigate to review step, then:

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });

  // 4. LOADING STATES
  describe('Loading States', () => {
    it('disables buttons and shows processing during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // ...navigate to review, click place order

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    });
  });

  // 5. ACCESSIBILITY
  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });

  // 6. EDGE CASES
  describe('Edge Cases', () => {
    it('shows empty cart message when cart has no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});
